    this.save();
    this.render();
    pulseOrb();
    announce(`${this.definition.name} recomeçada. Todas as posições aguardam.`);
  },

  activate() {
    this.render();
    if (this.definition.access === 'premium') void this.verifyPremium({ force:true });
  }
};

